"""Prepared only: invoke after Root final republish, Sauganash stage1, exclusive GPU grant."""
from pathlib import Path
import argparse,os,subprocess,json,hashlib,datetime,time,re
p=argparse.ArgumentParser();p.add_argument('--expected-source',required=True);p.add_argument('--expected-build',required=True);p.add_argument('--expected-build-sha256',required=True);a=p.parse_args()
assert os.environ.get('GPU_SLOT_GRANTED')=='post-b-boot','Root exclusive queued GPU grant required; do not run during Fort/Cobweb/Sauganash.'
R=Path('/tmp/chicago-west-wicket-20261109/chicago/4d');O=Path('/tmp/nov10-post-b-boot');SITE=R/'../../site/4d';sha=lambda q:hashlib.sha256(Path(q).read_bytes()).hexdigest()
source=subprocess.check_output(['git','rev-parse','HEAD'],cwd=R,text=True).strip();assert source==a.expected_source
assert not subprocess.check_output(['git','status','--porcelain'],cwd=R,text=True).strip(),'Root source must be clean before the pinned actual measurement'
build_path=SITE/'build.json';build=json.loads(build_path.read_text());assert build['version']==a.expected_build and sha(build_path)==a.expected_build_sha256
native=json.loads(Path('/tmp/nov10-final-three-native/B-NATIVE-RESULT.json').read_text());assert native['status'].startswith('PASS') and native['run_id']==42758213227
assert not (O/'COMMAND-RECEIPT.json').exists(),'This measurement has already been attempted; do not silently overwrite or auto-retry'
tool=R/'tools/measure_boot_payload.mjs';tool_sha=sha(tool);doc=(R/'docs/SITE-BUDGET.md').read_text();budget_match=re.search(r'boot payload budget[^0-9]*([0-9]+(?:\.[0-9]+)?)\s*MB',doc,re.I);assert budget_match;budget_bytes=float(budget_match.group(1))*1048576
binding={'status':'ACTUAL_MEASUREMENT_RUNNING_NOT_PASS','started_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'root_source_head':source,'published_build':build,'published_build_sha256':sha(build_path),'official_tool_sha256':tool_sha,'site_budget_doc_sha256':sha(R/'docs/SITE-BUDGET.md'),'budget_bytes_read_by_official_check':budget_bytes,'native_run':native['run_id'],'native_source':native['source'],'retained_native':native['retained_sha'],'pre_B_actual_boot_bytes':45932852,'claim_limit':'Official default first-visit actual gzip wire boot only, after Root final republish and Sauganash stage1. No refusal routes, forced tier, asset/hash waiver or Light-floor change. This is not whole-frame/shadow/FITS certification.'};(O/'INPUT-BINDINGS.json').write_text(json.dumps(binding,indent=2)+'\n')
cmd=['node','tools/measure_boot_payload.mjs','--json','--check','--entries',str(O/'boot-entries.json')];started=time.monotonic()
with (O/'official-boot.stdout.log').open('wb') as out,(O/'official-boot.stderr.log').open('wb') as err:
 result=subprocess.run(cmd,cwd=R,stdout=out,stderr=err,timeout=360)
row={'command':cmd,'cwd':str(R),'exit':result.returncode,'seconds':time.monotonic()-started,'stdout_sha256':sha(O/'official-boot.stdout.log'),'stderr_sha256':sha(O/'official-boot.stderr.log'),'expected_source':source,'expected_build':a.expected_build};(O/'COMMAND-RECEIPT.json').write_text(json.dumps(row,indent=2)+'\n')
raw=(O/'official-boot.stdout.log').read_text();measured,offset=json.JSONDecoder().raw_decode(raw.lstrip());(O/'ACTUAL-BOOT.json').write_text(json.dumps(measured,indent=2)+'\n')
assert sha(build_path)==a.expected_build_sha256 and sha(tool)==tool_sha,'Publication/tool changed during measurement'
assert subprocess.check_output(['git','rev-parse','HEAD'],cwd=R,text=True).strip()==source,'Root source moved during measurement'
report={'status':'PASS_ACTUAL_OFFICIAL_POST_B_BOOT' if result.returncode==0 and not measured['failures'] and measured['total_bytes']<=budget_bytes else 'FAIL_ACTUAL_OFFICIAL_POST_B_BOOT','binding':binding,'command':row,'actual':measured,'budget_bytes':budget_bytes,'headroom_bytes':budget_bytes-measured['total_bytes'],'delta_from_actual_pre_B_boot_bytes':measured['total_bytes']-45932852,'official_check_trailer':raw[offset:].strip(),'scope':'Actual boot payload only; no extrapolated whole B FITS, frame, calls, shadow, Light or production-promotion claim.'};(O/'FINAL-BOOT-RECEIPT.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({k:report[k] for k in ['status','headroom_bytes','delta_from_actual_pre_B_boot_bytes']},indent=2));raise SystemExit(0 if report['status'].startswith('PASS') else 1)
